    if (token.clase == nombre) {
        return token.valor == 0 && nombre_valido(token.texto);
    }
    const bool signo = token.clase == '+' || token.clase == '-' || token.clase == '*'
        || token.clase == '/' || token.clase == '%' || token.clase == '('
        || token.clase == ')' || token.clase == ';' || token.clase == '=';
    return token.valor == 0 && token.texto.empty()
        && (signo || token.clase == declaracion || token.clase == final_texto);
}

class Lector_tokens {
public:
    explicit Lector_tokens(const std::string& texto) : entrada_{texto} {
        if (texto.size() > 120) throw std::runtime_error("Text too long");
    }

    Token leer() {
        if (lleno_) {
            lleno_ = false;
            return guardado_;
        }
        return leer_token(entrada_);
    }

    void devolver(const Token& token) {
        if (lleno_) throw std::runtime_error("Buffer occupied");
        if (!token_valido(token)) throw std::runtime_error("Invalid token");
        guardado_ = token;
        lleno_ = true;
    }

    bool descartar_operacion() {
        if (entrada_.bad()) throw std::runtime_error("Serious stream failure");
        if (lleno_) {
            const Token pendiente = guardado_;
            lleno_ = false;
            if (pendiente.clase == ';') return true;
            if (pendiente.clase == final_texto) return false;
        }
        entrada_.clear();
        char c = '?';
        while (entrada_.get(c)) {
            if (c == ';') return true;
        }
        if (entrada_.bad() || !entrada_.eof()) throw std::runtime_error("Stream failure");
        return false;
    }

private:
    std::istringstream entrada_;
    bool lleno_ = false;
    Token guardado_{final_texto, 0, ""};
};

int resultado_en_dominio(int candidato) {
    if (candidato < -100 || candidato > 100) {
        throw std::runtime_error("Result out of range");
    }
    return candidato;
}

struct Vinculo {
    std::string nombre;
    int valor;
};

class Tabla_nombres {
public:
    bool contiene(const std::string& nombre_buscado) const {
        for (const Vinculo& dato : datos_) {
            if (dato.nombre == nombre_buscado) return true;
        }
        return false;
    }

    int consultar(const std::string& nombre_buscado) const {
        for (const Vinculo& dato : datos_) {
            if (dato.nombre == nombre_buscado) return dato.valor;
        }
        throw std::runtime_error("Undefined name");
    }

    void definir(const std::string& nuevo, int valor) {
        if (!nombre_valido(nuevo)) throw std::runtime_error("Invalid name");
        resultado_en_dominio(valor);
        if (contiene(nuevo)) throw std::runtime_error("Name already defined");
        if (datos_.size() >= 8) throw std::runtime_error("Table full");
        datos_.push_back(Vinculo{nuevo, valor});
    }

    void asignar(const std::string& existente, int valor) {
        resultado_en_dominio(valor);
        for (Vinculo& dato : datos_) {
            if (dato.nombre == existente) {
                dato.valor = valor;
                return;
            }
        }
        throw std::runtime_error("Undefined name");
    }

    const std::vector<Vinculo>& entradas() const {
        return datos_;
    }

private:
    std::vector<Vinculo> datos_;
};

int main() {
    Tabla_nombres tabla;
    tabla.definir("Section", 3);
    std::cout << "Original: " << tabla.consultar("Section") << "\n";
    Tabla_nombres candidata = tabla;
    candidata.asignar("Section", 7);
    std::cout << "Candidate: " << candidata.consultar("Section") << "\n";
    std::cout << "Discarded: " << tabla.consultar("Section") << "\n";
    Tabla_nombres segunda = tabla;
    segunda.asignar("Section", 12);
    tabla = segunda;
    std::cout << "Accepted: " << tabla.consultar("Section") << "\n";
    return 0;
}
